<?php
require __DIR__.'/includes/bootstrap.php';
require __DIR__.'/includes/service.php';
require __DIR__.'/includes/layout.php';
$error='';$receipt=null;
$suburbs=['Lynbrook','Lyndhurst','Hampton Park','Narre Warren South','Cranbourne West'];
$times=['Morning (7 am – 12 pm)','Afternoon (12 pm – 5 pm)','Evening (5 pm – 8 pm)','Flexible'];
$_SESSION['booking_nonce']??=bin2hex(random_bytes(24));
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
 checkCsrf();if(post('website',100)!=='')throw new DomainException('Unable to submit this request.');
 if(!hash_equals($_SESSION['booking_nonce'],post('nonce',100)))throw new DomainException('This request was already submitted. Please refresh to start a new booking.');
 limitRequest('booking:'.($_SERVER['REMOTE_ADDR']??''),8,3600);
 $name=post('name',100);$phone=post('phone',30);$email=strtolower(post('email',190));$suburb=post('suburb',80);$date=post('date',10);$time=post('time',40);$enquiry=post('enquiry',1000);
 if(mb_strlen($name)<2||(!preg_match('/^[+\d\s()\-]{8,30}$/D',$phone)||strlen(preg_replace('/\D/','',$phone))<8)||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Enter your name, a valid phone number, and email address.');
 if(!in_array($suburb,$suburbs,true)||!in_array($time,$times,true))throw new DomainException('Please select a service suburb and a preferred time.');
 $d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);
 if(!$d||$d->format('Y-m-d')!==$date||$date<date('Y-m-d')||$date>date('Y-m-d',strtotime('+1 year')))throw new DomainException('Choose a preferred date within the next year.');
 $pid=positiveInt(post('package_id',12),1,1000000);
 $ref=createBooking(['package_id'=>$pid,'name'=>$name,'phone'=>$phone,'email'=>$email,'suburb'=>$suburb,'date'=>$date,'time'=>$time,'enquiry'=>$enquiry]);
 $_SESSION['receipt']=['reference'=>$ref,'name'=>$name];$_SESSION['booking_nonce']=bin2hex(random_bytes(24));redirect('index.php?submitted=1#confirmation');
 }catch(DomainException $ex){$error=$ex->getMessage();}catch(Throwable $ex){error_log('Booking submission failed: '.$ex->getMessage());$error='Your request could not be saved. Please try again or call 0417 545 545.';}
}
if(isset($_GET['submitted']))$receipt=$_SESSION['receipt']??null;
$packages=q('SELECT * FROM booking_packages WHERE active=1 ORDER BY sort_order,id')->fetchAll();
$selected=is_string($_POST['package_id']??null)?$_POST['package_id']:(is_string($_GET['package']??null)?$_GET['package']:'');
pageStart('Book your next step');
?>
<div class="preview-banner">SAMPLE BOOKING PAGE <span>For review only. Requests here are stored in this separate booking system.</span></div>
<section class="booking-hero shell"><div><div class="eyebrow">CALM COACHING. CONFIDENT DRIVING.</div><h1>Your next step<br>starts behind<br>the wheel<span>.</span></h1><p>Choose your lesson, tell us when you’re free, and let Sanjeev take care of the details.</p><a class="button" href="#request">Book Now <span aria-hidden="true">＋</span></a><div class="hero-proof"><span>10+ years of experience</span><span>800+ successful students</span></div></div><aside class="journey-card"><div class="mini-label">A SIMPLE WAY TO GET STARTED</div><h2>Good driving.<br>Great support.</h2><ol><li><span>Choose your lesson</span><small>Find the right fit for your goals.</small></li><li><span>Request your preferred time</span><small>We’ll check Sanjeev’s availability.</small></li><li><span>Get your booking confirmed</span><small>Your lesson is confirmed personally.</small></li></ol><div class="journey-footer">Free doorstep pick-up in our five service suburbs.</div></aside></section>
<?php if($receipt):?><section class="shell" id="confirmation"><div class="confirmation"><span class="eyebrow">REQUEST SAVED</span><h2>Thanks, <?=e($receipt['name'])?>. You’re on the list.</h2><p>Your booking reference is <strong><?=e($receipt['reference'])?></strong>. Sanjeev will contact you to confirm a suitable time. Your preferred time is a request, not a confirmed appointment.</p><a href="#request">Request another lesson</a></div></section><?php endif;?>
<section class="lesson-section" id="lessons"><div class="shell"><div class="section-heading"><div><span class="eyebrow">LESSONS THAT FIT YOUR JOURNEY</span><h2>A little practice.<br>A lot more confidence.</h2></div><p>Clear prices. Patient coaching.<br>Choose what works for you.</p></div><div class="public-packages"><?php foreach($packages as $p):?><article class="lesson-card" data-package-suburb="<?=e($p['suburb_only'])?>"><div class="lesson-meta"><?=e($p['lesson_count'])?> lesson<?=(int)$p['lesson_count']===1?'':'s'?> · <?=e($p['duration_minutes'])?> min each</div><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><div class="lesson-bottom"><div><strong><?=money($p['total_cents'])?></strong><small>Total package price</small></div><a href="?package=<?=(int)$p['id']?>#request" class="text-button">Choose lesson</a></div></article><?php endforeach;?></div></div></section>
<section class="request-section shell" id="request"><div class="request-intro"><span class="eyebrow">LET’S FIND YOUR NEXT LESSON</span><h2>Tell us what<br>works for you.</h2><p>Submit your preferred date and time. Sanjeev will get in touch to confirm your schedule and pick-up details.</p><div class="contact-block"><small>HAVE A QUESTION?</small><a href="tel:0417545545">0417 545 545</a><a class="whatsapp" href="https://wa.me/61417545545">Chat on WhatsApp</a></div><div class="area-note"><strong>We come to you.</strong><p>Lynbrook, Lyndhurst, Hampton Park, Narre Warren South &amp; Cranbourne West.</p></div></div><div class="form-card"><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if(!$packages): emptyState('No lessons available yet','Please call Sanjeev to arrange your lesson.');else:?><form method="post" action="index.php#request" class="form-grid"><?=csrfField()?><input type="hidden" name="nonce" value="<?=e($_SESSION['booking_nonce'])?>"><div class="field full"><label for="package">Your lesson or package *</label><select id="package" name="package_id" required><option value="">Select a lesson or package</option><?php foreach($packages as $p):?><option value="<?=(int)$p['id']?>" <?=$selected==(string)$p['id']?'selected':''?>><?=e($p['name'])?> — <?=money($p['total_cents'])?> total</option><?php endforeach;?></select></div>
<?php foreach(['name'=>['Your name','text','e.g. Alex Smith','name'],'phone'=>['Phone / WhatsApp number','tel','04XX XXX XXX','tel'],'email'=>['Email address','email','you@example.com','email']] as $key=>$f):?><div class="field <?=$key==='email'?'full':''?>"><label for="<?=$key?>"><?=e($f[0])?> *</label><input id="<?=$key?>" type="<?=$f[1]?>" name="<?=$key?>" autocomplete="<?=$f[3]?>" maxlength="<?=$key==='email'?190:($key==='name'?100:30)?>" placeholder="<?=e($f[2])?>" required value="<?=e(is_string($_POST[$key]??null)?$_POST[$key]:'')?>"></div><?php endforeach;?>
<div class="field full"><label for="suburb">Your suburb *</label><select id="suburb" name="suburb" required><option value="">Select your service suburb</option><?php foreach($suburbs as $v):?><option <?=($_POST['suburb']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label for="date">Preferred date *</label><input id="date" name="date" type="date" required min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+1 year'))?>" value="<?=e(is_string($_POST['date']??null)?$_POST['date']:'')?>"></div><div class="field"><label for="time">Preferred time *</label><select id="time" name="time" required><option value="">Choose a time</option><?php foreach($times as $v):?><option <?=($_POST['time']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="field full"><label for="enquiry">Anything you’d like us to know?</label><textarea id="enquiry" name="enquiry" rows="3" maxlength="1000" placeholder="Your experience, test date, or preferred days…"><?=e(is_string($_POST['enquiry']??null)?$_POST['enquiry']:'')?></textarea></div><div class="honeypot" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><div class="full"><button class="button wide" type="submit">Send Booking Request</button><p class="form-disclaimer">No payment is collected here. Times are shown in Melbourne time. We use your details to manage your booking and contact you.</p></div></form><?php endif;?></div></section>
